def fib(n: int, memo: dict = None) -> int:
    """Return the nth Fibonacci number using memoization."""
    if memo is None:
        memo = {}
    if n <= 1:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
